import contextlib
import io
import runpy
import unittest


def rodar():
    """Roda solucao.py do zero e devolve tudo o que ele imprimiu."""
    saida = io.StringIO()
    with contextlib.redirect_stdout(saida):
        runpy.run_path("solucao.py")
    return saida.getvalue()


class TestOBilheteDoCinema(unittest.TestCase):
    def test_imprime_o_bilhete_completo(self):
        """o programa imprime o bilhete inteiro, da faixa ao total"""
        self.assertEqual(rodar(), "BILHETE DO CINEMA\nfaixa: adolescente\npreco: 16.65\ntaxa do fim de semana: 5.0\ntotal: 21.65\n")

    def test_a_faixa_da_idade(self):
        """a faixa da idade sai do if/elif/else, nao digitada a mao"""
        idade = 15
        if idade < 12:
            faixa = "infantil"
        elif 12 <= idade < 18:
            faixa = "adolescente"
        elif idade >= 60:
            faixa = "veterano"
        else:
            faixa = "adulto"
        self.assertEqual(rodar(), "BILHETE DO CINEMA\nfaixa: " + faixa + "\npreco: 16.65\ntaxa do fim de semana: 5.0\ntotal: 21.65\n")

    def test_o_preco_da_meia_entrada(self):
        """o preco da meia e a metade do valor cheio, escolhido numa linha so"""
        valor_cheio = 33.3
        preco = valor_cheio / 2
        self.assertEqual(rodar(), "BILHETE DO CINEMA\nfaixa: adolescente\npreco: " + str(preco) + "\ntaxa do fim de semana: 5.0\ntotal: 21.65\n")

    def test_a_taxa_do_fim_de_semana(self):
        """a taxa e 5.0 quando o dia e fim de semana e 0.0 nos outros dias"""
        dia = "sabado"
        if dia == "sabado" or dia == "domingo":
            taxa = 5.0
        else:
            taxa = 0.0
        self.assertEqual(rodar(), "BILHETE DO CINEMA\nfaixa: adolescente\npreco: 16.65\ntaxa do fim de semana: " + str(taxa) + "\ntotal: 21.65\n")

    def test_o_total_arredondado(self):
        """o total e o preco mais a taxa, arredondado em duas casas"""
        total = 33.3 / 2 + 5.0
        self.assertEqual(rodar(), "BILHETE DO CINEMA\nfaixa: adolescente\npreco: 16.65\ntaxa do fim de semana: 5.0\ntotal: " + str(round(total, 2)) + "\n")
